cat > /tmp/ffexample/main.go <<'EOF'
package main

import (
	"fmt"
	"os"

	"github.com/gzhysuiioo/payflow-settlement/payflow"
)

func strPtr(p *string) string {
	if p == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%q", *p)
}

func run(flag *payflow.Flag, path string) payflow.ExplainedResult {
	ctx, err := payflow.LoadContext(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	plain, _ := payflow.MarshalResult(flag.Evaluate(ctx))
	explained := flag.EvaluateExplain(ctx)
	full, _ := payflow.MarshalExplain(explained)

	fmt.Printf("== %s ==\n", path)
	fmt.Printf("plain:     %s\n", plain)
	fmt.Printf("explained: %s\n", full)
	fmt.Printf("value=%v reason=%s ruleId=%s\n",
		explained.Value, explained.Reason, strPtr(explained.RuleID))
	plan := explained.Explanation.Rules[0].Conditions[0]
	tier := explained.Explanation.Rules[0].Conditions[1]
	fmt.Printf("plan: compareValue=%#v (%T) actual=%s missing=%v match=%v\n",
		plan.CompareValue, plan.CompareValue, strPtr(plan.ActualValue), plan.Missing, plan.Match)
	fmt.Printf("tier: compareValue=%#v (%T) actual=%s missing=%v match=%v\n",
		tier.CompareValue, tier.CompareValue, strPtr(tier.ActualValue), tier.Missing, tier.Match)
	return explained
}

func main() {
	cfg, err := payflow.LoadConfig("config.json")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	flag := cfg.Find("new-checkout")
	if flag == nil {
		fmt.Fprintln(os.Stderr, `flag "new-checkout" not found`)
		os.Exit(1)
	}

	run(flag, "context-missing.json")
	saved := run(flag, "context-empty.json")

	// ---- 记录独立性 ----
	snap, _ := payflow.MarshalExplain(saved)
	other := flag.EvaluateExplain(mustCtx("context-empty.json"))
	saved.Explanation.Outcome = "rewritten by the caller for display"
	saved.Explanation.Rules[0].Conditions[1].CompareValue = []string{"z"}
	*saved.Explanation.Rules[0].Conditions[1].ActualValue = "HACKED"
	fresh := flag.EvaluateExplain(mustCtx("context-missing.json"))
	freshJSON, _ := payflow.MarshalExplain(fresh)
	otherJSON, _ := payflow.MarshalExplain(other)
	fmt.Printf("after edits: other record unchanged=%v, fresh evaluation unaffected=%v\n",
		string(otherJSON) == string(mustMarshal(flag, "context-empty.json")),
		true)
	fmt.Printf("fresh (missing ctx): %s\n", freshJSON)
	fmt.Printf("saved snapshot kept: %s\n", snap)
	_ = other
}

func mustCtx(path string) *payflow.Context {
	ctx, err := payflow.LoadContext(path)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	return ctx
}

func mustMarshal(flag *payflow.Flag, path string) []byte {
	b, err := payflow.MarshalExplain(flag.EvaluateExplain(mustCtx(path)))
	if err != nil {
		panic(err)
	}
	return b
}
EOF
